        let _c7_train_a_missing = _c7_train_a_first_anchor;
        TrainABox { _c7_train_a_missing }._c7_train_a_missing
    };
    // C7_TRAIN_A_REGION_SPLIT
    let second_bias: i64 = {
        let _c7_train_a_second_anchor = 11_i64;
        _c7_train_a_second_anchor
    };
